queries.sphinxql:
create table t(f text, a int);
insert into t values(0,'a b c',123), (0,'a b d',123),(0,'a d e',123);
insert into t(id,f,a) values(10,'alpha some words beta gamma',123), (11,'alpha some words beta delta',123);
CREATE TABLE near_bug_repro (title text);
INSERT INTO near_bug_repro (id, title) VALUES (1, 'alpha some words beta gamma');

    select * from t;
    select * from t where match('a -b -c'); show meta;
	select count(*) from t where match('(alpha NEAR/5 beta) !delta');
	select count(*) from near_bug_repro where match('(@title (alpha NEAR/5 beta)) !@title (delta)');
	drop table t;
	drop table near_bug_repro;
